        'art_culture_heritage.art_culture_of_karnataka.karnataka_temple_architecture_sculpture.badami_chalukya_architecture_aihole_badami_pattadakal', 'badami_chalukya_architecture_aihole_badami_pattadakal', 'Badami Chalukya Architecture (Aihole, Badami, Pattadakal)', 4,
        'Subtopic_Entity', 'Art, Culture & Heritage', 'art_culture_heritage', 'art_culture_heritage.art_culture_of_karnataka.karnataka_temple_architecture_sculpture',
