        '[UPSC: Prelims-GS1, Mains-GS1] [KAS: Prelims-P1, Mains-GS1] [SSC: GA]', 'Primary planetary winds: Trade Winds (Northeast and Southeast Trades), Prevailing Westerlies (Roaring Forties, Furious Fifties, Shrieking Sixties in open Southern Ocean), Polar Easterlies; Periodic daily winds: Land and sea breezes, Anabatic (upslope daytime valley breeze) vs Katabatic (downslope nighttime mountain wind); Regional hot winds: Loo (Indo-Gangetic plain), Chinook (snow-eater, eastern Rockies), Foehn (Alps), Sirocco (Sahara to Mediterranean), Harmattan (Doctor wind, West Africa), Khamsin; Regional cold winds: Mistral (Rhone valley France), Bora (Adriatic coast), Blizzard (polar prairies), Pampero (Argentina pampas).', ARRAY['Trade Winds & Prevailing Westerlies', 'Roaring Forties & Furious Fifties', 'Land and Sea Breezes', 'Anabatic & Katabatic Winds', 'Hot Winds (Chinook, Harmattan, Loo, Foehn)', 'Cold Winds (Mistral, Bora, Blizzard)']::text[], ARRAY['Planetary', 'Winds', 'World', 'Regional', 'Local', 'Primary', 'planetary', 'winds', 'Trade', 'Northeast', 'Southeast', 'Trades', 'Prevailing', 'Westerlies', 'Roaring', 'Forties', 'Furious', 'Fifties', 'Shrieking', 'Sixties', 'open', 'Southern', 'Ocean', 'Polar', 'Easterlies', 'Periodic', 'daily', 'Land', 'sea', 'breezes', 'Anabatic', 'upslope', 'daytime', 'valley', 'breeze', 'Katabatic', 'downslope', 'nighttime', 'mountain', 'wind', 'hot', 'Loo', 'Indo', 'Gangetic', 'plain', 'Chinook', 'snow', 'eater', 'eastern', 'Rockies', 'Foehn', 'Alps', 'Sirocco', 'Sahara', 'Mediterranean', 'Harmattan', 'Doctor', 'West', 'Africa', 'Khamsin', 'cold', 'Mistral', 'Rhone', 'France', 'Bora', 'Adriatic', 'coast', 'Blizzard', 'polar', 'prairies', 'Pampero', 'Argentina', 'pampas', 'Sea', 'Breezes', 'Hot', 'Cold']::text[],
