        ARRAY[]::text[], ARRAY['geography_earth_systems', 'geography_earth_systems.oceanography_marine_systems', 'geography_earth_systems.oceanography_marine_systems.ocean_water_dynamics']::text[], '{"upsc": ["Prelims-GS1", "Mains-GS1"], "kas": ["Prelims-P1", "Mains-GS1"], "ssc": ["GA"]}'::jsonb,
        '[UPSC: Prelims-GS1, Mains-GS1] [KAS: Prelims-P1, Mains-GS1] [SSC: GA]', 'Wave physics: Wind blowing over fetch generating surface orbital motion; Wave Anatomy: Crest (highest point), Trough (lowest point), Wave Height (vertical distance from trough to crest), Wavelength (horizontal distance between two consecutive crests), Wave Period (time for one wavelength to pass a point), Wave Frequency; Orbital motion of water particles decaying with depth (wave base = wavelength / 2); Shoaling in shallow water where friction slows wave base, steepens wave height, and creates breaking surf (Spilling, Plunging, Surging breakers); Constructive vs Destructive waves shaping coastal morphology.', ARRAY['Wave Anatomy (Crest, Trough, Height, Period)', 'Wind Fetch and Wind Duration', 'Orbital Particle Motion & Wave Base', 'Wave Shoaling & Breakers (Surf Zone)', 'Constructive vs Destructive Waves']::text[], ARRAY['Ocean', 'Waves', 'Mechanics', 'Wave', 'Parameters', 'Energy', 'physics', 'Wind', 'blowing', 'over', 'fetch', 'generating', 'surface', 'orbital', 'motion', 'Anatomy', 'Crest', 'highest', 'point', 'Trough', 'lowest', 'Height', 'vertical', 'distance', 'trough', 'crest', 'Wavelength', 'horizontal', 'between', 'two', 'consecutive', 'crests', 'Period', 'time', 'one', 'wavelength', 'pass', 'Frequency', 'Orbital', 'water', 'particles', 'decaying', 'depth', 'wave', 'base', 'Shoaling', 'shallow', 'where', 'friction', 'slows', 'steepens', 'height', 'creates', 'breaking', 'surf', 'Spilling', 'Plunging', 'Surging', 'breakers', 'Constructive', 'Destructive', 'waves', 'shaping', 'coastal', 'morphology', 'Fetch', 'Duration', 'Particle', 'Motion', 'Base', 'Breakers', 'Surf', 'Zone']::text[],
