    (
        'geography_earth_systems.indian_physical_geography_monsoon_architecture.soils_natural_vegetation_of_india.major_soil_types_of_india_and_land_degradation', 'major_soil_types_of_india_and_land_degradation', 'Major Soil Groups of India: ICAR Classification & Land Degradation', 4,
