        ARRAY[]::text[], ARRAY['geography_earth_systems', 'geography_earth_systems.human_geography_population_settlements', 'geography_earth_systems.human_geography_population_settlements.human_settlements_urban_systems']::text[], '{"upsc": ["Prelims-GS1", "Mains-GS1"], "kas": ["Prelims-P1", "Mains-GS1"], "ssc": ["GA"]}'::jsonb,
        '[UPSC: Prelims-GS1, Mains-GS1] [KAS: Prelims-P1, Mains-GS1] [SSC: GA]', 'Geographical morphology of rural dwellings: Physical, cultural, and historical determinants of settlement patterns (water points/wet point settlements, defensibility, fertile soil); Four standard morphological types: Clustered / Compact / Nucleated settlements (closely built houses, common in fertile alluvial plains of Ganga and valley tracts), Semi-clustered / Fragmented settlements (segregation or grouping of specific castes/clans on the periphery, Gujarat plains, Rajasthan), Hamleted settlements (physically separated units bearing local names like Panna, Para, Palli, Nagla, Dhani across Middle Ganga plain and lower Himalayas), and Dispersed / Isolated settlements (isolated farmsteads or huts scattered over hills, Western Ghats, Meghalaya, Himachal Pradesh); Vernacular building materials adapted to local micro-climates (adobe, thatch, stone masonry, bamboo).', ARRAY['Clustered / Nucleated Settlements', 'Semi-Clustered Morphology', 'Hamleted Settlements (Panna / Para / Palli)', 'Dispersed / Isolated Mountain Huts', 'Wet Point Settlement Determinants', 'Vernacular Architecture']::text[], ARRAY['Rural', 'Settlement', 'Morphology', 'Spatial', 'Types', 'Vernacular', 'Architecture', 'Geographical', 'morphology', 'rural', 'dwellings', 'Physical', 'cultural', 'historical', 'determinants', 'settlement', 'patterns', 'water', 'points', 'wet', 'point', 'settlements', 'defensibility', 'fertile', 'soil', 'Four', 'standard', 'morphological', 'types', 'Clustered', 'Compact', 'Nucleated', 'closely', 'built', 'houses', 'common', 'alluvial', 'plains', 'Ganga', 'valley', 'tracts', 'Semi', 'clustered', 'Fragmented', 'segregation', 'grouping', 'specific', 'castes', 'clans', 'periphery', 'Gujarat', 'Rajasthan', 'Hamleted', 'physically', 'separated', 'units', 'bearing', 'local', 'names', 'like', 'Panna', 'Para', 'Palli', 'Nagla', 'Dhani', 'across', 'Middle', 'plain', 'lower', 'Himalayas', 'Dispersed', 'Isol