    (
        'geography_earth_systems.economic_resource_geography.global_indian_distribution_of_natural_resources.energy_resources_fossil_fuels_nuclear_renewables', 'energy_resources_fossil_fuels_nuclear_renewables', 'Energy Resources: Coal, Hydrocarbons, Critical Minerals & Renewables', 4,
        'Subtopic_Entity', 'Geography & Earth Systems', 'geography_earth_systems', 'geography_earth_systems.economic_resource_geography.global_indian_distribution_of_natural_resources',
        ARRAY[]::text[], ARRAY['geography_earth_systems', 'geography_earth_systems.economic_resource_geography', 'geography_earth_systems.economic_resource_geography.global_indian_distribution_of_natural_resources']::text[], '{"upsc": ["Prelims-GS1", "Mains-GS1"], "kas": ["Prelims-P1", "Mains-GS1"], "ssc": ["GA"]}'::jsonb,
        '[UPSC: Prelims-GS1, Mains-GS1] [KAS: Prelims-P1, Mains-GS1] [SSC: GA]', 'Spatial mapping of conventional and non-conventional energy resources: Coal (Gondwana coal ~250 million years old, non-coking/bituminous, 98% Indian reserves located in river valleys: Damodar valley with Jharia oldest/richest coalfield and Raniganj, Son valley with Singrauli, Mahanadi valley with Talcher, Wardha-Godavari valley; Tertiary coal ~15-60 million years old, high sulphur/moisture, Makum in Assam, lignite brown coal at Neyveli Tamil Nadu; Global: Appalachian basin USA, Ruhr Germany, Shanxi China, Newcastle Australia); Petroleum & Natural Gas (Onshore: Brahmaputra valley Digboi oldest oilfield, Naharkatiya, Moran-Hugrijan; Gujarat basin Ankleshwar, Kalol, Cambay; Rajasthan Barmer basin Mangala, Bhagyam, Aishwarya; Offshore: Mumbai High on continental shelf, Bassein gas field, Krishna-Godavari deepwater basin KG-D6; Strategic Petroleum Reserves: Padur, Mangalore, Visakhapatnam, Chandikhol); Nuclear Energy & Critical Minerals (Uranium: Jaduguda and Narwapahar in Singhbhum Jharkhand, Tummalapalle in Andhra Pradesh largest reserve in carbonate rock; Thorium: Monazite beach sands of Kerala Chavara and Odisha; Critical Minerals & Rare Earth Elements: Lithium discovery in Reasi J&K and Mandya Karnataka); Renewable Energy Geography (Solar parks: Bhadla Rajasthan largest, Pavagada Karnataka, Kurnool; Wind energy corridors: Muppandal wind farm in Tamil Nadu, Jaisalmer, coastal Gujarat; Green Hydrogen mission hubs).', ARRAY['Gondwana Coal Basins (Jharia & Raniganj)', 'Tertiary Lignite (Neyveli)', 'Offshore Mumbai High & KG-D6 Gas Basin', 'Strategic Petroleum Reserves (SPR)', 'Uranium (Jaduguda & Tummalapalle)', 'Monazite Thorium Beach Sands', 'Solar Parks (Bhadla & Pavagada)', 'Muppandal Wind Energy Corridor']::text[], ARRAY['Energy', 'Resources', 'Coal', 'Hydrocarbons', 'Critical', 'Minerals', 'Renewables', 'Spatial', 'mapping', 'conventional', 'non', 'energy', 'resources', 'Gondwana', 'coal', '~250', 'million', 'years', 'old', 'coking', 'bituminous', '98%', 'Indian', 'reserves', 'located', 'river', 'valleys', 'Damodar', 'valley', 'Jharia', 'oldest', 'richest', 'coalfield', 'Raniganj', 'Son', 'Singrauli', 'Mahanadi', 'Talcher', 'Wardha', 'Godavari', 'Tertiary', '~15', '60', 'high', 'sulphur', 'moisture', 'Makum', 'Assam', 'lignite', 'brown', 'Neyveli', 'Tamil', 'Nadu', 'Global', 'Appalachian', 'basin', 'USA', 'Ruhr', 'Germany', 'Shanxi', 'China', 'Newcastle', 'Australia', 'Petroleum', 'Natural', 'Gas', 'Onshore', 'Brahmaputra', 'Digboi', 'oilfield', 'Naharkatiya', 'Moran', 'Hugrijan', 'Gujarat', 'Ankleshwar', 'Kalol', 'Cambay', 'Rajasthan', 'Barmer', 'Mangala', 'Bhagyam', 'Aishwarya', 'Offshore', 'Mumbai', 'High', 'continental', 'shelf', 'Bassein', 'gas', 'field', 'Krishna', 'deepwater', 'KG', 'D6', 'Strategic', 'Reserves', 'Padur', 'Mangalore', 'Visakhapatnam', 'Chandikhol', 'Nuclear', 'Uranium', 'Jaduguda', 'Narwapahar', 'Singhbhum', 'Jharkhand', 'Tummalapalle', 'Andhra', 'Pradesh', 'largest', 'reserve', 'carbonate', 'rock', 'Thorium', 'Monazite', 'beach', 'sands', 'Kerala', 'Chavara', 'Odisha', 'Rare', 'Earth', 'Elements', 'Lithium', 'discovery', 'Reasi', 'Mandya', 'Karnataka', 'Renewable', 'Geography', 'Solar', 'parks', 'Bhadla', 'Pavagada', 'Kurnool', 'Wind', 'corridors', 'Muppandal', 'wind', 'farm', 'Jaisalmer', 'coastal', 'Green', 'Hydrogen', 'mission', 'hubs', 'Basins', 'Lignite', 'Basin', 'SPR', 'Beach', 'Sands', 'Parks', 'Corridor']::text[],
