    (
        'geography_earth_systems.economic_resource_geography.agricultural_geography_and_food_security.cropping_patterns_major_food_commercial_crops_india', 'cropping_patterns_major_food_commercial_crops_india', 'Cropping Patterns & Geographic Belts of Food & Commercial Crops', 4,
        'Subtopic_Entity', 'Geography & Earth Systems', 'geography_earth_systems', 'geography_earth_systems.economic_resource_geography.agricultural_geography_and_food_security',
        ARRAY[]::text[], ARRAY['geography_earth_systems', 'geography_earth_systems.economic_resource_geography', 'geography_earth_systems.economic_resource_geography.agricultural_geography_and_food_security']::text[], '{"upsc": ["Prelims-GS1", "Mains-GS1"], "kas": ["Prelims-P1", "Mains-GS1"], "ssc": ["GA"]}'::jsonb,
        '[UPSC: Prelims-GS1, Mains-GS1] [KAS: Prelims-P1, Mains-GS1] [SSC: GA]', 'Geographical distribution, climatic thresholds, and agrarian zoning of major crops: Major cropping seasons: Kharif (monsoon sowings June-July: Rice, Maize, Jowar, Bajra, Cotton, Jute, Groundnut), Rabi (winter sowings October-November: Wheat, Barley, Gram, Mustard), and Zaid (summer inter-cropping: watermelons, cucumbers, vegetables); Food grain geography: Rice (staple crop requiring >100 cm rainfall, high temperature >25 deg C, alluvial clayey soils; West Bengal, UP, Punjab, coastal deltas), Wheat (temperate crop requiring cool growing season 10-15 deg C, bright sunshine at harvest, 50-75 cm rainfall, well-drained loams; Punjab, Haryana, UP, MP), Millets / Nutri-Cereals (hardy, drought-resistant C4 crops: Jowar in Maharashtra/Karnataka, Bajra in Rajasthan, Ragi in Karnataka); Pulses (leguminous nitrogen-fixing crops, MP, Rajasthan, Maharashtra); Commercial crops: Sugarcane (tropical/subtropical, 100-150 cm rainfall; UP, Maharashtra, Karnataka), Cotton (black regur soil, 210 frost-free days, Gujarat, Maharashtra, Telangana), Jute (golden fiber, warm humid deltaic climate; West Bengal, Assam, Bihar), Tea (plantation crop requiring acidic highland slopes, 150-250 cm rainfall, shade trees; Assam Brahmaputra valley, Darjeeling, Nilgiris), Coffee (plantation crop requiring well-drained volcanic/humus soils, 150-200 cm rain; Karnataka 70% national output with Arabica and Robusta in Kodagu/Chikkamagaluru, Wayanad Kerala).', ARRAY['Kharif, Rabi & Zaid Seasons', 'Rice & Wheat Agro-Climatic Requirements', 'Millets / Nutri-Cereals (Jowar, Bajra, Ragi)', 'Cotton Belt (Black Regur Soil & 210 Frost-Free Days)', 'Sugarcane Production Belts', 'Tea (Assam & Darjeeling) & Coffee (Karnataka)', 'Pulses & Nitrogen Fixation']::text[], ARRAY['Cropping', 'Patterns', 'Geographic', 'Belts', 'Food', 'Commercial', 'Crops', 'Geographical', 'distribution', 'climatic', 'thresholds', 'agrarian', 'zoning', 'major', 'crops', 'Major', 'cropping', 'seasons', 'Kharif', 'monsoon', 'sowings', 'June', 'July', 'Rice', 'Maize', 'Jowar', 'Bajra', 'Cotton', 'Jute', 'Groundnut', 'Rabi', 'winter', 'October', 'November', 'Wheat', 'Barley', 'Gram', 'Mustard', 'Zaid', 'summer', 'inter', 'watermelons', 'cucumbers', 'vegetables', 'grain', 'geography', 'staple', 'crop', 'requiring', '100', 'cm', 'rainfall', 'high', 'temperature', '25', 'deg', 'alluvial', 'clayey', 'soils', 'West', 'Bengal', 'UP', 'Punjab', 'coastal', 'deltas', 'temperate', 'cool', 'growing', 'season', '10', '15', 'bright', 'sunshine', 'harvest', '50', '75', 'well', 'drained', 'loams', 'Haryana', 'MP', 'Millets', 'Nutri', 'Cereals', 'hardy', 'drought', 'resistant', 'C4', 'Maharashtra', 'Karnataka', 'Rajasthan', 'Ragi', 'Pulses', 'leguminous', 'nitrogen', 'fixing', 'Sugarcane', 'tropical', 'subtropical', '150', 'black', 'regur', 'soil', '210', 'frost', 'free', 'days', 'Gujarat', 'Telangana', 'golden', 'fiber', 'warm', 'humid', 'deltaic', 'climate', 'Assam', 'Bihar', 'Tea', 'plantation', 'acidic', 'highland', 'slopes', '250', 'shade', 'trees', 'Brahmaputra', 'valley', 'Darjeeling', 'Nilgiris', 'Coffee', 'volcanic', 'humus', '200', 'rain', '70%', 'national', 'output', 'Arabica', 'Robusta', 'Kodagu', 'Chikkamagaluru', 'Wayanad', 'Kerala', 'Seasons', 'Agro', 'Climatic', 'Requirements', 'Belt', 'Black', 'Regur', 'Soil', 'Frost', 'Free', 'Days', 'Production', 'Nitrogen', 'Fixation']::text[],
