        'civil_services', ARRAY['civil_services']::text[]
    ),
    (
        'geography_earth_systems.world_mapping_geopolitical_locations.strategic_straits_chokepoints_canals.strategic_canals_suez_panama_taiwan_strait_mapping', 'strategic_canals_suez_panama_taiwan_strait_mapping', 'Canals & Passages: Suez Canal, Panama Canal, Taiwan Strait & Gibraltar', 4,
        'Subtopic_Entity', 'Geography & Earth Systems', 'geography_earth_systems', 'geography_earth_systems.world_mapping_geopolitical_locations.strategic_straits_chokepoints_canals',
        ARRAY[]::text[], ARRAY['geography_earth_systems', 'geography_earth_systems.world_mapping_geopolitical_locations', 'geography_earth_systems.world_mapping_geopolitical_locations.strategic_straits_chokepoints_canals']::text[], '{"upsc": ["Prelims-GS1", "Mains-GS1"], "kas": ["Prelims-P1", "Mains-GS1"], "ssc": ["GA"]}'::jsonb,
        '[UPSC: Prelims-GS1, Mains-GS1] [KAS: Prelims-P1, Mains-GS1] [SSC: GA]', 'Man-made international canals and critical oceanic waterways: Suez Canal (193 km sea-level artificial waterway opened in 1869 across the Isthmus of Suez in Egypt, connecting Mediterranean Sea at Port Said to Red Sea at Port Tewfik/Suez; no locks required; enables direct transit between Europe and Asia bypassing Cape of Good Hope); Panama Canal (82 km artificial ship canal opened in 1914 across the Isthmus of Panama, connecting Atlantic Ocean at Colón to Pacific Ocean at Panama City; operates with a freshwater lock system lifting ships 26m to Gatun Lake; expanded Neopanamax locks 2016); Taiwan Strait / Formosa Strait (separates mainland China Fujian province from Taiwan; connects South China Sea with East China Sea); Strait of Gibraltar (connects Atlantic Ocean to Mediterranean Sea; separates Spain/Gibraltar in Europe from Morocco/Ceuta in Africa; 14 km width at narrowest point); Sunda Strait (between Java and Sumatra) and Lombok Strait (deepwater alternative between Bali and Lombok across the Wallace Line); Bering Strait (separates Chukchi Peninsula Russia from Seward Peninsula Alaska USA, connecting Arctic Ocean to Bering Sea).', ARRAY['Suez Canal (Port Said to Suez)', 'Panama Canal & Gatun Lake Locks', 'Taiwan Strait (Formosa Strait)', 'Strait of Gibraltar (Europe-Africa Chokepoint)', 'Sunda & Lombok Straits (Indonesia)', 'Bering Strait (Russia-Alaska Boundary)']::text[], ARRAY['Canals', 'Passages', 'Suez', 'Canal', 'Panama', 'Taiwan', 'Strait', 'Gibraltar', 'Man', 'made', 'international', 'canals', 'critical', 'oceanic', 'waterways', '193', 'km', 'sea', 'level', 'artificial', 'waterway', 'opened', '1869', 'across', 'Isthmus', 'Egypt', 'connecting', 'Mediterranean', 'Sea', 'Port', 'Said', 'Red', 'Tewfik', 'no', 'locks', 'required', 'enables', 'direct', 'transit', 'between', 'Europe', 'Asia', 'bypassing', 'Cape', 'Good', 'Hope', '82', 'ship', 'canal', '1914', 'Atlantic', 'Ocean', 'Col', 'Pacific', 'City', 'operates', 'freshwater', 'lock', 'system', 'lifting', 'ships', '26m', 'Gatun', 'Lake', 'expanded', 'Neopanamax', '2016', 'Formosa', 'separates', 'mainland', 'China', 'Fujian', 'province', 'connects', 'South', 'East', 'Spain', 'Morocco', 'Ceuta', 'Africa', '14', 'width', 'narrowest', 'point', 'Sunda', 'Java', 'Sumatra', 'Lombok', 'deepwater', 'alternative', 'Bali', 'Wallace', 'Line', 'Bering', 'Chukchi', 'Peninsula', 'Russia', 'Seward', 'Alaska', 'USA', 'Arctic', 'Locks', 'Chokepoint', 'Straits', 'Indonesia', 'Boundary']::text[],
